doc = {"a": {"b": [1, {"c": 2}]}, "d": 3}
def walk(node, path=""):
    if isinstance(node, dict):
        for k, v in node.items(): yield from walk(v, path + "." + k if path else k)
    elif isinstance(node, list):
        for i, v in enumerate(node): yield from walk(v, "%s[%d]" % (path, i))
    else:
        yield path, node
for p, v in walk(doc):
    print("%-10s = %r" % (p, v))

