doc = {"orders": [{"total": 10}, {"total": 25}, {"total": 7}]}
def select(doc, expr):
    node = doc
    for step in expr.split("."):
        if step.endswith("[*]"): node = [x for item in node[step[:-3]] for x in ([item] if not isinstance(item, list) else item)]
        else: node = node[step]
    return node
print(select(doc, "orders[*]"))

