a = {"name": "a"}; b = {"name": "b", "parent": a}; a["child"] = b
def walk(node, path="", active=None):
    active = active or set()
    if id(node) in active:
        print(path, "-> [cycle]"); return
    active.add(id(node))
    print(path or "root", "=", node.get("name"))
    for k, v in node.items():
        if isinstance(v, dict): walk(v, path + "/" + k, active)
    active.remove(id(node))
walk(a)

