doc = {"a": {"b": [1, 2]}, "c": "x"}
flat = {}
def flat_walk(node, path=""):
    if isinstance(node, dict):
        for k, v in node.items(): flat_walk(v, (path + "." + k) if path else k)
    elif isinstance(node, list):
        for i, v in enumerate(node): flat_walk(v, "%s[%d]" % (path, i))
    else: flat[path] = node
flat_walk(doc)
for p in sorted(flat): print("%-8s = %r" % (p, flat[p]))

